window.openService=function(){const body=`<p class="helper"><b>*</b> Campos obrigatórios. O funcionário responsável aceitará o serviço depois que ele for criado.</p><div class="form-grid">${field('Cliente','clientId',{options:clientOptions()})}${field('Vendedor responsável','sellerId',{options:(db.sellers||[]).map(x=>({value:x.id,label:x.name}))})}<div class="form-field span2"><label>Extintores do serviço</label><div id="serviceExtRows"></div><button type="button" class="btn btn-soft btn-small" onclick="addServiceExtRow()">＋ Adicionar tipo</button><p class="helper">Escolha o tipo, o peso e a quantidade de cada grupo.</p></div>${field('Tipo de serviço','serviceType',{required:true,options:['Manutenção','Inspeção','Recarga','Teste hidrostático','Instalação','Outro'].map(x=>({value:x,label:x}))})}${field('Data do serviço','date',{type:'date',required:true,value:new Date().toISOString().slice(0,10)})}<div class="form-field"><label>Total da ordem</label><strong id="serviceTotal">R$ 0,00</strong><input name="price" type="hidden" value="0.00"></div>${field('Componentes / peças previstas','parts')}${field('Observações iniciais','notes',{cls:'span2'})}</div>`;openModal('Registrar manutenção / serviço',body,async form=>{const client=db.clients.find(x=>x.id===val(form,'clientId')),seller=(db.sellers||[]).find(x=>x.id===val(form,'sellerId')),rows=[...document.querySelectorAll('#serviceExtRows .service-ext-row')];if(!client&&!seller){toast('Selecione um cliente ou vendedor.');return false}if(!rows.length){toast('Adicione ao menos um tipo de extintor.');return false}const items=[];let total=0;for(const row of rows){const type=row.querySelector('[name="extType"]').value,kg=isWaterExtinguisher(type)?'':row.querySelector('[name="extKg"]').value,qty=Number(row.querySelector('[name="extQty"]').value||0),config=typeFor(type,kg);if(!type||(!isWaterExtinguisher(type)&&!kg)||!config||qty<1){toast('Confira tipo, peso e quantidade.');return false}total+=qty*Number(config.price||0);for(let i=0;i<qty;i++)items.push({type,kg,model:config.model||'',unitPrice:Number(config.price||0),status:db.settings.stages?.[0]||'Solicitado',serial:'',seal:'',maintenanceYear:'',hydroYear:'',notes:'',replacedParts:[],extraParts:'',painted:false,history:[{status:db.settings.stages?.[0]||'Solicitado',at:new Date().toISOString()}]});}const createdAt=new Date().toISOString(),service={id:id(),code:'FS-'+Math.random().toString(36).slice(2,8).toUpperCase(),clientId:client?.id||'',clientName:client?.name||'Desconhecido',clientPhone:client?.phone||'',sellerId:seller?.id||'',sellerName:seller?.name||'Desconhecido',date:val(form,'date'),serviceType:val(form,'serviceType'),employeeId:'',employeeName:'',price:Math.round(total*100)/100,maintenanceValid:'',hydroValid:'',parts:val(form,'parts'),notes:val(form,'notes'),items,serial:'',type:[...new Set(items.map(x=>x.type))].join(', '),history:[{at:createdAt,action:'Serviço registrado',description:`${items.length} extintor(es) aguardando aceite de um funcionário.`}]};db.services.push(service);if(!await save()){db.services.pop();saveLocal();return false}renderPage();toast('Serviço criado e disponível para aceite.');return {afterClose:()=>setTimeout(()=>window.serviceOrder(service.id),80)};});addServiceExtRow();};
window.serviceOrder=function(serviceId){const service=db.services.find(x=>x.id===serviceId);if(!service)return;const items=serviceItems(service),groups=groupExtinguishers(items),rows=groups.map(g=>`<tr><td>${esc(g.type)}${g.kg&&!isWaterExtinguisher(g.type)?' · '+esc(g.kg)+' kg':''}</td><td>${g.items.length}</td><td>${money(g.items.reduce((sum,x)=>sum+Number(x.unitPrice||0),0))}</td></tr>`).join('');openModal('Ficha da ordem de serviço',`<div class="service-order"><div class="order-head"><div><div class="eyebrow">Ordem de serviço</div><h2>${esc(db.settings.company||'FogoSeguro')}</h2><p>${esc(service.code)}</p></div><div class="order-code"><small>${date(service.date)}</small></div></div><div class="order-parties"><div><small>Cliente</small><b>${esc(service.clientName||'—')}</b></div><div><small>Serviço</small><b>${esc(service.serviceType||'Manutenção')}</b></div><div><small>Responsável</small><b>${esc(service.employeeName||'Aguardando aceite')}</b></div></div><table class="order-table"><thead><tr><th>Tipo</th><th>Qtd.</th><th>Subtotal</th></tr></thead><tbody>${rows}</tbody></table><p><b>Observações:</b> ${esc(service.notes||'—')}</p></div>`,()=>true,'Fechar');};
